entries[214910] = { ["name"] = "Goldrinn's Fury", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Scythe of Elune\nYour control over Goldrinn's power grows, allowing your spells to become increasingly devastating.\n\nIncreases all damage by 5%." }
entries[214911] = { ["name"] = "Fangs of the First", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Fangs of Ashamane\nYour bond with the avatar of Ashamane strengthens, allowing you to further channel her great power.\n\nIncreases all damage by 5%." }
entries[214912] = { ["name"] = "Ursoc's Bond", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Claws of Ursoc\nYour bond with Ursoc's mighty avatar grows stronger by the day, making you more resilient to enemy attacks.\n\nIncreases Armor by 6%." }
entries[214913] = { ["name"] = "G'Hanir's Bloom", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires G'Hanir, the Mother Tree\nAs the forests grow, so too does G'Hanir, even in its diminished state. Your spells blossom with increasing effectiveness.\n\nIncreases healing done by 5%." }
entries[214914] = { ["name"] = "Spiritbound", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Titanstrike\nHati's bond with you grows ever stronger, increasing his and your effectiveness in battle.\n\nIncreases all of your damage and your pets' damage by 5.00%." }
entries[214915] = { ["name"] = "Windflight Arrows", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Thas'dorah, Legacy of the Windrunners\nThe ancient magic within this bow grants increasing power over the wind, allowing arrows to slice through the air with ease, to lethal effect.\n\nIncreases all damage by 5%." }
entries[214916] = { ["name"] = "Voice of the Wild Gods", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Talonclaw, Spear of the Wild Gods\nWild Gods of many names look to the spearbearer as their champion. More and more of their power flows through you as long as Talonclaw is yours to wield.\n\nIncreases all damage by 5%." }
entries[214917] = { ["name"] = "Ancient Power", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Aluneth, Greatstaff of the Magna\nThe chaotic entity Aluneth bends to your will, further empowering your spells.\n\nIncreases Arcane damage by 5%." }
entries[214918] = { ["name"] = "Empowered Spellblade", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Felo'melorn\nFelo'melorn acts as a conduit for your spells, further empowering their devastating effects.\n\nIncreases Fire damage by 5%." }
entries[214919] = { ["name"] = "Spellborne", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Ebonchill, Greatstaff of Alodi\nPower flows freely through Ebonchill, allowing you to harness more and more of its frightening potential.\n\nIncreases Frost damage by 5%." }
entries[214920] = { ["name"] = "Wanderer's Hardiness", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Fu Zan, the Wanderer's Companion\nThe power within Fu Zan seeps into your very being, increasing your hardiness in battle.\n\nIncreases Armor by 17%." }
entries[214921] = { ["name"] = "Mistweaving", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Sheilun, Staff of the Mists\nSheilun's power over the mists, almost overwhelming at first, has become second-nature over time, allowing you even greater mastery of your powers.\n\nIncreases healing done by 5%." }
entries[214922] = { ["name"] = "Windborne Blows", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Fists of the Heavens\nThe wind whispers your name, and flows behind your fists. The longer you spend with the Fists of the Heavens, the more furious your blows.\n\nIncreases all damage by 5%." }
entries[214923] = { ["name"] = "Silver Touch", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires The Silver Hand\nYour just cause and actions bond you with the hammer of the mighty watcher Tyr, and through it, your righteous spells grow increasingly powerful.\n\nIncreases healing done by 5%." }
entries[214924] = { ["name"] = "Unrelenting Light", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Truthguard\nAs its power increases, Truthguard shrugs off blows with increasing ease.\n\nIncreases Armor by 10%." }
entries[214925] = { ["name"] = "Forbidden Flame", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Light's Wrath\nThe unstable power within Light's Wrath succumbs to your command, further empowering your spells.\n\nIncreases all damage, healing, and absorbs by 5%." }
entries[214926] = { ["name"] = "Beacon of Light", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires T'uure, Beacon of the Naaru\nYour bond with T'uure has only grown over time, increasing the already noticeable power it has granted you.\n\nIncreases healing done by 5%." }
entries[214927] = { ["name"] = "Darkening Whispers", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Xal'atath, Blade of the Black Empire\nXal'atath whispers dark words of power into your ear, granting you secret knowledge to make your spells increasingly powerful.\n\nIncreases Shadow damage by 5%." }
entries[214928] = { ["name"] = "Slayer's Precision", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires The Kingslayers\nCountless kills have only increased the deadliness of these already fearsome blades.\n\nIncreases all damage by 5%." }
entries[214929] = { ["name"] = "Cursed Steel", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires The Dreadblades\nThe cursed blades fill you with unsettling amounts of power, further increasing the deadliness of your strikes.\n\nIncreases all damage by 5%." }
entries[214930] = { ["name"] = "Legionblade", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Fangs of the Devourer\nThe more you fight with the fangs, the more quickly and precisely they seem to strike.\n\nIncreases all damage by 5%." }
entries[214931] = { ["name"] = "Stormkeeper's Power", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires The Fist of Ra-den\nHarnessing the power of Ra-den, your spells become increasingly devastating.\n\nIncreases all damage by 5%." }
entries[214932] = { ["name"] = "Earthshattering Blows", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Doomhammer\nYour mastery of doomhammer increases, further empowering your attacks.\n\nIncreases all damage by 5%." }
entries[214933] = { ["name"] = "Flow of the Tides", ["text"] = "Rank 1/ 20 Artifact Trait\nRequires Sharas'dal, Scepter of Tides\nImmense power flows through Sharas'dal, and your mastery of it only increases over time\n\nIncreases healing done by 5%." }
