entries[215129] = { ["name"] = "Champion: Altruis the Sufferer", ["text"] = "Instant\nWhen no one else would stand against Illidan's method of fighting the Burning Legion regardless of the cost, there was Altruis. As strong a demon hunter as you have ever known, his fighting ability is topped only by his keen intellect and the respect he has gained for pushing to change the methods of the Illidari." }
